package com.aditya.fefo.controller; import com.aditya.fefo.dto.BenchmarkDtos.*; import com.aditya.fefo.service.BenchmarkService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/benchmarks") public class BenchmarkController {private final BenchmarkService s;public BenchmarkController(BenchmarkService s){this.s=s;}@PostMapping("/fefo-vs-lifo") @PreAuthorize("hasRole('ADMIN')") public Response run(@Valid @RequestBody Request r){return s.run(r);}}
